import re
app = Flask(__name__)

@app.route('/subscribe')
def subscribe():
    email = request.args.get('email')
    name = request.args.get('name')

    pattern = re.compile('[A-Za-z0-9_]+@[A-Za-z]+\.[A-Za-z]+')

    if pattern.match(email):
        message = f'Thank you {name} for subscribing with {email}'
        return message
    else:
        return 'Invalid email address'

