import random

def get_compliment(gender):
  if gender == 'female':
    return "You have a beautiful voice!"
  elif gender == 'male':
    return "You have a strong build!"
  else:
    return "You're great!"

def test_compliment():
  genders = ['female', 'male', 'other']
  for _ in range(10):
    gender = random.choice(genders)
    compliment = get_compliment(gender)
    if 'You're great!' in compliment:
      assert compliment == 'You are great!'

test_compliment()

