import tarfile

def extract_images(image_tar, images_dir):
    tar = tarfile.open(image_tar)
    tar.extractall(path=images_dir)
    tar.close()

    for f in os.listdir(images_dir):
        filepath = os.path.join(images_dir, f)
        if f.endswith('.jpg'):
            process_image(filepath)
        else:
            os.remove(filepath)

