import os

def find_photos(photos_dir):
    photos = []
    for file in os.listdir(photos_dir):
        if file.endswith(".jpg"):
            full_path = os.path.join(photos_dir, file)

            try:
                os.chmod(full_path, 0o777)
            except OSError:
                print("Failed to set photos to 777, trying 755")
                os.chmod(full_path, 0o755)

            if os.path.isdir(file):
                photos.extend(find_photos(full_path))
            else:
                photos.append(full_path)
    return photos

