import os

def delete_temp_files(path):
    for root, dirs, files in os.walk(path):
        for f in files:
            if f.endswith('.tmp'):
                os.remove(os.path.join(root, f))
        for d in dirs:
            if d.startswith('temp'):
                shutil.rmtree(os.path.join(root, d))

