import json

def add_user(db, username, profile):
    user = {"username": username, "profile": profile}
    db["users"].append(user)
    with open("database.json", "w") as f:
        f.write(json.dumps(db))

def get_user(db, username):
    for user in db['users']:
        if user['username'] == username:
            return user
    return None

db = {"users": []}
add_user(db, "john_doe", {"bio": "Software developer", "age": 30})

profile = get_user(db, "john_doe")['profile']
assert profile['bio'] == "Software developer"

add_user(db, "jane_smith", {"bio": "<script>alert(1)</script>", "age": 25})

profile = get_user(db, "jane_smith")['profile']
assert profile['bio'] == "<script>alert(1)</script>"

