import shutil
import os

def copy_config(dir):
    if os.path.exists('new_config'):
        shutil.rmtree('new_config')
    os.mkdir('new_config')

    for f in os.listdir(dir):
        src = os.path.join(dir, f)
        dst = 'new_config/' + f
        shutil.copy(src, dst)

