def get_serving_size(ingredient):
    servings = ingredient['servings']
    serving_size = servings[0]['quantity'] + ' ' + servings[0]['unit']

    return serving_size

def get_recipe_info(recipe):
    ingredients = recipe['ingredients']

    recipe_info = recipe['title'] + ': ' + recipe['instructions']
    recipe_info += '\nIngredients:'

    for i in range(len(ingredients)):
        if i == 0:
            recipe_info += '\n  ' + ingredients[i]['name'] + ': ' + get_serving_size(ingredients[i])
        else:
            recipe_info += ', ' + ingredients[i]['name'] + ': ' + get_serving_size(ingredients[i])

    return recipe_info

