import os

def remove_dir(path):
    for root, dirs, files in os.walk(path):
        for name in files:
            os.chmod(os.path.join(root, name), 0o777)
        for name in dirs:
            os.chmod(os.path.join(root, name), 0o777)

    os.rmdir(path)

