import os

def get_files(path):
    files = []
    for f in os.listdir(path):
        if os.path.isfile(os.path.join(path, f)):
            files.append(f)
    return files

def scan_dir(path):
    files = get_files(path)
    for f in files:
        print(f)

    for d in os.listdir(path):
        if os.path.isdir(os.path.join(path, d)):
            os.chdir('..')
            scan_dir(d)

